<?php
declare(strict_types=1);
require_once __DIR__.'/includes/session_org.php';require_once __DIR__.'/includes/org_context.php';require_once __DIR__.'/includes/org_manager_guard.php';org_require_manager();if(!function_exists('h')){function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}}$staffOrgId=(int)orgActiveOrgId();$staffRows=[];try{$st=$dbh->prepare("SELECT om.id,om.member_type,om.relationship_label,om.role_id,om.status,COALESCE(s.fullname,m.fullname,s.username,m.username,'Staff member') fullname,COALESCE(s.email,m.email,'') email,COALESCE(s.last_seen,m.last_seen) last_seen FROM org_members om LEFT JOIN staff_accounts s ON om.member_type='staff' AND s.id=om.member_id LEFT JOIN managers m ON om.member_type='manager' AND m.id=om.member_id WHERE om.org_id=:org AND om.status=1 ORDER BY om.id DESC");$st->execute([':org'=>$staffOrgId]);$staffRows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}$staffPermissionsEmbedded=!empty($staffPermissionsEmbedded);if(!$staffPermissionsEmbedded){$pageTitle='Staff & Permissions';require_once __DIR__.'/includes/org_page_shell.php';org_page_shell_open($pageTitle,'<link rel="stylesheet" href="css/commerce-hub.css?v=17">');org_page_body_open('commerce-page');}
?>
