place-items:center;font-weight:900}.stp-role,.stp-active{padding:3px 6px;border-radius:999px;background:#ede9fe;color:#6d28d9}.stp-active{background:#dcfce7;color:#15803d}.stp-pages{display:flex;justify-content:space-between;align-items:center;padding:7px;font-size:7px}.stp-pages b{border:1px solid #9db7ff;border-radius:5px;padding:5px 8px;color:#143dff}.stp-role-row,.stp-invite{display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid var(--b);font-size:8px}.stp-role-row i{width:27px;height:27px;border-radius:6px;background:#eef3ff;color:#143dff;display:grid;place-items:center}.stp-role-row span,.stp-invite span{flex:1}.stp-role-row small,.stp-invite small{display:block;color:var(--m)}.stp-perms{display:grid;grid-template-columns:110px 1fr;gap:8px}.stp-perm-nav div{padding:6px;font-size:8px}.stp-perm-nav div:first-child{background:#eef3ff;color:#143dff;border-radius:5px}.stp-checks{width:100%;border-collapse:collapse}.stp-checks td,.stp-checks th{font-size:7px;padding:5px;border-bottom:1px solid var(--b);text-align:center}.stp-checks td:first-child{text-align:left}.stp-checks input{accent-color:#143dff}@media(max-width:900px){.stp{height:auto;overflow:visible}.stp-body{grid-template-columns:1fr}.stp-nav{display:flex;overflow:auto}.stp-tab{min-width:140px}.stp-main,.stp-side{grid-template-rows:auto}}</style>
<main class="stp"><header class="stp-head"><div><p class="stp-crumb"><a href="#settings" data-sales-nav="settings">Home › Store Settings</a> › Staff &amp; Permissions</p><h1>Staff &amp; Permissions</h1><p class="stp-sub">Manage your staff members and control their access to store resources.</p></div><button class="stp-save">Save Changes</button></header><div class="stp-body"><aside class="stp-nav"><a class="stp-tab" href="#settings" data-sales-nav="settings"><i class="fa fa-building-o"></i>Store Information</a><a class="stp-tab" href="#payment-billing" data-sales-nav="payment-billing"><i class="fa fa-credit-card"></i>Payment &amp; Billing</a><a class="stp-tab" href="#shipping-settings" data-sales-nav="shipping-settings"><i class="fa fa-truck"></i>Shipping Settings</a><a class="stp-tab" href="#tax-settings" data-sales-nav="tax-settings"><i class="fa fa-file-text-o"></i>Tax Settings</a><a class="stp-tab" href="#settings-notifications" data-sales-nav="settings-notifications"><i class="fa fa-bell-o"></i>Notifications</a><a class="stp-tab on" href="#staff-permissions" data-sales-nav="staff-permissions"><i class="fa fa-users"></i>Staff &amp; Permissions</a><a class="stp-tab" href="#policies" data-sales-nav="policies"><i class="fa fa-shield"></i>Policies</a><a class="stp-tab danger" href="#danger-zone" data-sales-nav="danger-zone"><i class="fa fa-trash-o"></i>Danger Zone</a></aside><div class="stp-main"><section class="stp-card"><button class="stp-add">Add Staff</button><h2>Staff Members</h2><p>Manage staff accounts, roles, and their access levels.</p><div class="stp-filter"><input placeholder="Search staff by name or email..."><select><option>All Roles</option></select></div><table class="stp-table"><tr><th>Staff Member</th><th>Role</th><th>Status</th><th>Last Active</th></tr><?php if(!$staffRows):?><tr><td colspan="4">No staff members yet.</td></tr><?php endif;?><?php foreach(array_slice($staffRows,0,6) as $r):$name=trim((string)$r['fullname'])?:'Staff';$role=$r['member_type']==='manager'?'Admin':(trim((string)$r['relationship_label'])?:'Staff');?><tr><td><div class="stp-person"><span class="stp-avatar"><?=h(mb_strtoupper(mb_substr($name,0,1)))?></span><span><strong><?=h($name)?></strong><br><?=h((string)$r['email'])?></span></div></td><td><span class="stp-role"><?=h(ucfirst($role))?></span></td><td><span class="stp-active">Active</span></td><td><?=h((string)($r['last_seen']??'—'))?></td></tr><?php endforeach;?></table><div class="stp-pages"><span>Showing <?=min(6,count($staffRows))?> of <?=count($staffRows)?> staff members</span><span><b>1</b> &nbsp; 2 &nbsp; 3</span></div></section><section class="stp-card"><h2>Role Permissions</h2><p>Select a role to view and manage its permissions.</p><div class="stp-perms"><div class="stp-perm-nav"><?php foreach(['General','Orders','Products','Customers','Inventory','Reports','Marketing','Settings'] as $x):?><div><?=$x?></div><?php endforeach;?></div><table class="stp-checks"><tr><th>Permission</th><th>View</th><th>Add</th><th>Edit</th><th>Delete</th><th>Export</th></tr><?php foreach(['Dashboard','Orders','Products','Customers','Reports','Settings'] as $i=>$x):?><tr><td><strong><?=$x?></strong></td><?php for($j=0;$j<5;$j++):?><td><input type="checkbox" <?=($i<5&&($j===0||$j===2||$j===4))?'checked':''?>></td><?php endfor;?></tr><?php endforeach;?></table></div></section></div><div class="stp-side"><section class="stp-card"><h2>Roles Overview</h2><p>Summary of roles in your store.</p><?php foreach([['fa-shield','Admin','Full access to all settings and features.'],['fa-briefcase','Manager','Manage orders, products and customers.'],['fa-pencil','Editor','Create and edit content and products.'],['fa-headphones','Customer Support','Access to customer and order support.'],['fa-eye','Viewer','View data and basic reports.']] as $r):?><div class="stp-role-row"><i class="fa <?=$r[0]?>"></i><span><strong><?=$r[1]?></strong><small><?=$r[2]?></small></span><b><?=max(1,(int)ceil(count($staffRows)/5))?></b></div><?php endforeach;?></section><section class="stp-card"><h2>Pending Invites</h2><p>Invited staff who haven't joined yet.</p><div class="stp-invite"><span><strong>Pending staff invitation</strong><small>Awaiting account activation</small></span><button class="stp-add">Resend</button></div></section></div></div></main>
